    productDetails: '{"form":"تونر ترطيب وتنقية يومي","size":"200ml (منزلي) / 1000ml (احترافي)","target":"الترطيب وتنقية البشرة","technology":"مجمع مستخلصات النباتات مع نظام توازن الأس الهيدروجيني","keyBenefits":"ترطيب عميق، تهدئة البشرة، تنقية الملمس، توازن الأس الهيدروجيني","usage":"صباحاً ومساءً بعد التنظيف","skinType":"جميع أنواع البشرة","application":"ضع بقطعة قطن أو ربت برفق باليدين","formulation":"صيغة خفيفة سريعة الامتصاص","origin":"كوريا الجنوبية"}',
