    keyFeatures: null,
    benefits: '["التفتيح - يساعد في تفتيح بقع التصبغ وتحسين لون البشرة بشكل عام","الترطيب العميق - يوفر ترطيب مكثف، مما يجعل البشرة ناعمة ومرنة","الحماية المضادة للأكسدة - يحمي من الجذور الحرة، مما يقلل علامات الشيخوخة","تغذية البشرة - يوفر العناصر الغذائية الأساسية لتعزيز صحة البشرة ومظهرها","تنشيط الكولاجين - يحفز إنتاج الكولاجين لبشرة أكثر صلابة وشباباً","دعم إضافي ضد الأشعة فوق البنفسجية - الأستازانتين يساعد عند الإجهاد الضوئي لكنه لا يغني عن واقي الشمس"]',
    ingredients: '[{"name":"الأستازانتين","description":"مضاد أكسدة قوي أقوى بـ 6000 مرة من فيتامين C. يساعد في تقليل تصبغ البشرة الناجم عن الجذور الحرة والتعرض للشمس."},{"name":"مجمع VITA 12","description":"يوفر العناصر الغذائية للبشرة، ويساعد في زيادة إنتاج الكولاجين، ويمنع فقدان ماء البشرة."},{"name":"Gluconolactone","description":"حمض Poly-Hydroxy (PHA) يحسن لون البشرة من خلال تقشير خلايا الجلد الميتة وترطيب البشرة."},{"name":"مستخلص جذر Glycyrrhiza Uralensis (عرق السوس)","description":"يمنع التصبغ من خلال منع تنشيط التيروزيناز، ويضيء البشرة."},{"name":"زيت بذور Macadamia Ternifolia","description":"يحتوي على حمض اللينوليك، الذي يمنع فقدان الماء عبر البشرة ويخلق حاجز وقائي طبيعي."},{"name":"حمض الأسكوربيك (فيتامين C)","description":"مضاد أكسدة طبيعي يحمي البشرة من الأضرار الناجمة عن الأشعة فوق البنفسجية بسبب الجذور الحرة."},{"name":"السيراميد NP","description":"يعزز حاجز الدهون الوقائي الطبيعي للبشرة ويحسن الترطيب طويل الأمد."}]',
