    productDetails: '{"form":"كريم مضاد للتجاعيد متعدد الوظائف","size":"50غ (العناية المنزلية) / 250غ (المهني)","target":"مكافحة التجاعيد وتفتيح البشرة","technology":"باكوتشيول مع البروبوليس والكولاجين وليبوزوم حاجز الدهون","keyBenefits":"تقليل التجاعيد، التثبيت، التفتيح، الحماية المضادة للأكسدة","usage":"صباحاً ومساءً — تدليك لطيف","skinType":"جميع أنواع البشرة، خاصة الناضجة","origin":"كوريا الجنوبية"}',
    keyFeatures: null,
    benefits: '["تقليل التجاعيد - ينعم الخطوط الدقيقة والتجاعيد، ويحسن ملمس البشرة","التثبيت - يعزز متانة ومرونة البشرة لمظهر أكثر شباباً","تخليق الكولاجين - يعزز إنتاج الكولاجين لتجديد البشرة","الحماية المضادة للأكسدة - يحمي البشرة من الإجهاد التأكسدي والأضرار البيئية","التفتيح - يوحد لون البشرة ويضيف إشراقاً طبيعياً","الترطيب العميق - يوفر رطوبة مكثفة لبشرة منتفخة وتبدو صحية"]',
    ingredients: '[{"name":"الباكوتشيول","description":"بديل طبيعي للريتينول (0.1٪)، معروف بخصائصه المضادة للشيخوخة وبملفه اللطيف والمستقر ضوئياً."},{"name":"مستخلص البروبوليس","description":"مضاد أكسدة طبيعي يدعم العناية المثبتة مع الكولاجين."},{"name":"الكولاجين والإيلاستين المتحللان","description":"مركب دعم ECM يساعد على تعزيز مظهر المتانة والمرونة."},{"name":"الأدينوزين","description":"مكون مضاد للشيخوخة (0.04٪) يساعد في تقليل مظهر التجاعيد."},{"name":"النياسيناميد","description":"فيتامين B3 (2٪) يفتح البشرة ويحسّن اللون ويدعم حاجز البشرة."},{"name":"زبدة بذور المانجو","description":"تغذية وراحة (0.8٪) ضمن عمود مضادات الأكسدة."},{"name":"ليبوزوم حاجز الدهون (سيراميد NP، كوليسترول، فيتوسفينجوزين)","description":"دهون أساسية تقوي حاجز البشرة وتدعم توصيل المكونات."}]',
    howToUse: "طبّقي طبقة رقيقة على الوجه والرقبة ومنطقة الصدر. دلكي برفق حتى الامتصاص. استخدميه صباحاً ومساءً. اتبعيه بواقي الشمس نهاراً.",
